<?php require_once 'includes/config.php'; require_login();$pdo=db();$id=(int)($_GET['id']??0);$u=user();$st=$pdo->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$st->execute([$id,$u['id']]);$o=$st->fetch();if(!$o){http_response_code(404);exit('Order not found.');}$st=$pdo->prepare('SELECT oi.*,p.name,p.image FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?');$st->execute([$id]);$items=$st->fetchAll();$title='Order #'.$id;require 'includes/header.php';?><div class="d-flex justify-content-between"><div><span class="eyebrow">ORDER DETAILS</span><h1 class="section-title">#<?=$o['id']?></h1></div><a class="btn btn-outline-purple" href="invoice.php?id=<?=$o['id']?>">Print Invoice</a></div><div class="panel p-4 mt-3"><div class="row g-4"><div class="col-md-7"><h5>Items</h5><?php foreach($items as $i):?><div class="d-flex gap-3 align-items-center border-bottom py-3"><img src="<?=e($i['image'])?>" style="width:65px;height:65px;object-fit:cover;border-radius:10px"><div class="flex-grow-1"><strong><?=e($i['name'])?></strong><div class="text-secondary">Qty <?=$i['quantity']?></div></div><strong><?=money($i['unit_price']*$i['quantity'])?></strong></div><?php endforeach;?></div><div class="col-md-5"><h5>Delivery</h5><p class="text-secondary"><?=nl2br(e($o['address_text']))?></p><h5>Summary</h5><div class="d-flex justify-content-between"><span>Subtotal</span><b><?=money($o['subtotal'])?></b></div><div class="d-flex justify-content-between"><span>Shipping</span><b><?=money($o['shipping'])?></b></div><div class="d-flex justify-content-between"><span>Discount</span><b>-<?=money($o['discount'])?></b></div><hr><div class="d-flex justify-content-between fs-5"><strong>Total</strong><strong class="text-purple"><?=money($o['total'])?></strong></div></div></div></div><?php require 'includes/footer.php';?>
